g-item\" @click=\"showImportDialog\">\n        <div class=\"setting-info\">\n          <div class=\"setting-name\">📥 从文件恢复</div>\n          <div class=\"setting-desc\">从 JSON 备份文件恢复数据</div>\n        </div>\n        <i class=\"el-icon-arrow-right\" style=\"color: var(--text-placeholder)\"></i>\n      </div>\n\n      <!-- 清空数据 -->\n      <div class=\"setting-item danger\" @click=\"clearAllData\">\n        <div class=\"setting-info\">\n          <div class=\"setting-name\">🗑️ 清空所有数据</div>\n          <div class=\"setting-desc\">不可恢复，请先导出备份</div>\n        </div>\n        <i class=\"el-icon-arrow-right\" style=\"color: var(--text-placeholder)\"></i>\n      </div>\n    </div>\n\n    <!-- 统计信息 -->\n    <div class=\"card\">\n      <div class=\"section-title\">📊 当前数据</div>\n      <div class=\"data-info\">\n        <div class=\"data-row\">\n          <span>物品数量</span>\n          <span>{{ itemCount }} 件</span>\n        </div>\n        <div class=\"data-row\">\n          <span>分类数量</span>\n          <span>{{ catCount }} 个</span>\n        </div>\n        <div class=\"data-row\">\n          <span>存储估算</span>\n          <span>{{ storageSize }}</span>\n        </div>\n      </div>\n    </div>\n\n    <!-- 关于 -->\n    <div class=\"card\">\n      <div class=\"section-title\">ℹ️ 关于</div>\n      <div class=\"about-info\">\n        <p>个人物品管理 v1.1</p>\n        <p style=\"font-size: 12px; color: var(--text-placeholder); margin-top: 4px\">\n          数据保存在本地浏览器，换设备请使用导出功能备份\n        </p>\n      </div>\n    </div>\n\n    <!-- 隐藏的文件输入框 -->\n    <input\n      ref=\"importFile\"\n      type=\"file\"\n      accept=\".json\"\n      style=\"display: none\"\n      @change=\"onImportFile\"\n    />\n  </div>\n</template>\n\n<script>\nimport {\n  loadSettings,\n  saveSettings,\n  updateSetting,\n  exportBackup,\n  importBackup,\n  loadItems,\n  loadCategories,\n  saveItems,\n  saveCategories,\n  getCategoryById\n} from '@/store/index'\nimport { formatFileSize } from '@/utils/format'\n\nexport default {\n  name: 'Settings',\n  data() {\n    return {\n      darkMode: false,\n      followSystem: false,\n      itemCount: 0,\n      catCount: 0,\n      storageSize: ''\n    }\n  },\n  mounted() {\n    this.initDarkMode()\n    this.loadData()\n  },\n  beforeDestroy() {\n    // 移除系统主题监听\n    if (this._systemListener) {\n      window.matchMedia('(prefers-color-scheme: dark)').removeListener(this._systemListener)\n    }\n  },\n  methods: {\n    initDarkMode() {\n      const settings = loadSettings()\n      this.followSystem = settings.followSystem || false\n      this.applyDarkMode()\n      if (this.followSystem) {\n        this._systemListener = (e) => {\n          this.darkMode = e.matches\n          this.applyDarkMode()\n        }\n        window.matchMedia('(prefers-color-scheme: dark)').addListener(this._systemListener)\n      }\n    },\n\n    applyDarkMode() {\n      const root = document.documentElement\n      if (this.darkMode) {\n        root.setAttribute('data-theme', 'dark')\n      } else {\n        root.removeAttribute('data-theme')\n      }\n    },\n\n    toggleDarkMode(val) {\n      this.darkMode = val !== undefined ? val : !this.darkMode\n      this.followSystem = false\n      updateSetting('darkMode', this.darkMode)\n      updateSetting('followSystem', false)\n      this.applyDarkMode()\n    },\n\n    toggleFollowSystem(val) {\n      this.followSystem = val\n      updateSetting('followSystem', this.followSystem)\n      if (this.followSystem) {\n        const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches\n        this.darkMode = prefersDark\n        updateSetting('darkMode', prefersDark)\n      }\n      this.applyDarkMode()\n    },\n\n    loadData() {\n      this.itemCount = loadItems().length\n      this.catCount = loadCategories().length\n      const size = JSON.stringify(localStorage).length\n      this.storageSize = formatFileSize(size * 2) // 估算（实际会更大）\n    },\n\n    // ============ 导出 JSON ============\n    exportJSON() {\n      const data = exportBackup()\n      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })\n      const url = URL.createObjectURL(blob)\n      const a = document.createElement('a')\n      const date = new Date().toISOString().slice(0, 10)\n      a.href = url\n      a.download = `物品备份-${date}.json`\n      a.click()\n      URL.revokeObjectURL(url)\n      this.$message.success('JSON 备份已下载')\n    },\n\n    // ============ 导入 ============\n    showImportDialog() {\n      this.$confirm(\n        '<p>请选择导入模式：</p><p style=\"font-size:13px;color:#888;margin-top:8px\"><b>完全覆盖</b>：用备份文件替换所有现有数据<br><b>合并追加</b>：将备份中的新数据合并进来</p>',\n        '导入备份',\n        {\n          confirmButtonText: '选择文件',\n          cancelButtonText: '取消',\n          dangerouslyUseHTMLString: true,\n          type: 'info'\n        }\n      ).then(() => {\n        this.$refs.importFile.click()\n      }).catch(() => {})\n    },\n\n    onImportFile(e) {\n      const file = e.target.files[0]\n      if (!file) return\n      const reader = new FileReader()\n      reader.onload = (ev) => {\n        try {\n          const data = JSON.parse(ev.target.result)\n          this.$confirm(\n            '确认导入？建议先导出当前数据备份。',\n            '确认导入',\n            { type: 'warning' }\n          ).then(() => {\n            this.doImport(data)\n          }).catch(() => {})\n        } catch (err) {\n          this.$message.error('文件格式错误，无法解析')\n        }\n      }\n      reader.readAsText(file)\n      e.target.value = ''\n    },\n\n    doImport(data, mode = 'merge') {\n      try {\n        importBackup(data, mode)\n        this.loadData()\n        this.$message.success('导入成功')\n      } catch (err) {\n        this.$message.error('导入失败：' + err.message)\n      }\n    },\n\n    // ============ 清空数据 ============\n    clearAllData() {\n      this.$prompt(\n        '此操作不可恢复！请输入「确认清空」以继续：',\n        '清空所有数据',\n        {\n          confirmButtonText: '确认清空',\n          cancelButtonText: '取消',\n          type: 'warning'\n        }\n      ).then(({ value }) => {\n        if (value !== '确认清空') {\n          this.$message.warning('输入不正确，操作已取消')\n          return\n        }\n        localStorage.removeItem('items')\n        localStorage.removeItem('categories')\n        this.loadData()\n        this.$message.success('所有数据已清空')\n      }).catch(() => {})\n    }\n  }\n}\n</script>\n\n<style scoped>\n.settings-page {\n  padding-bottom: 30px;\n}\n\n.setting-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px 0;\n  border-bottom: 1px solid var(--border-color);\n  cursor: pointer;\n}\n\n.setting-item:last-child {\n  border-bottom: none;\n}\n\n.setting-item.danger .setting-name {\n  color: var(--danger);\n}\n\n.setting-name {\n  font-size: 15px;\n  color: var(--text-primary);\n}\n\n.setting-desc {\n  font-size: 12px;\n  color: var(--text-placeholder);\n  margin-top: 2px;\n}\n\n.data-info {\n  margin-top: 8px;\n}\n\n.data-row {\n  display: flex;\n  justify-content: space-between;\n  padding: 8px 0;\n  border-bottom: 1px solid var(--border-color);\n  font-size: 14px;\n  color: var(--text-primary);\n}\n\n.data-row:last-child {\n  border-bottom: none;\n}\n\n.about-info {\n  font-size: 14px;\n  color: var(--text-primary);\n  line-height: 1.6;\n}\n</style>\n"],"sourceRoot":""}]);
